mapper.select:
SELECT  FROM iam.roles

    scope = #{scope}
    AND id > #{afterId}

ORDER BY id ASC LIMIT #{fetchSize}

mapper.update:
UPDATE iam.roles SET name = COALESCE(#{name,jdbcType=VARCHAR}, name),
    description = COALESCE(#{description,jdbcType=VARCHAR}, description),
    status = COALESCE(#{status,jdbcType=VARCHAR}, status) WHERE id = #{id}
